"""
Accounts Payable / Receivable Blueprint
Thin routing layer — all business logic is in services.ap_service.
"""

from flask import Blueprint, render_template, request, redirect, url_for, flash
from flask_login import login_required, current_user
from models import db, Vendor, Invoice, InvoicePayment, ChartOfAccounts, Project
from services.ap_service import create_invoice, record_payment, void_invoice, APServiceError
from datetime import datetime, date
from decimal import Decimal
from functools import wraps
from sqlalchemy import func

ap_bp = Blueprint('ap', __name__, url_prefix='/ap')


def treasurer_required(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        if current_user.role not in ['Admin', 'Treasurer']:
            flash('Permission denied.', 'error')
            return redirect(url_for('index'))
        return f(*args, **kwargs)
    return decorated_function


# ==================== VENDORS ====================

@ap_bp.route('/vendors')
@login_required
@treasurer_required
def vendors():
    search = request.args.get('search', '').strip()
    show_inactive = request.args.get('show_inactive', '').lower() == 'true'

    query = Vendor.query.filter_by(organization_id=current_user.organization_id)
    if search:
        query = query.filter(Vendor.name.ilike(f'%{search}%'))
    if not show_inactive:
        query = query.filter_by(active=True)

    return render_template('ap/vendors.html',
                           vendors=query.order_by(Vendor.name).all(),
                           search=search,
                           show_inactive=show_inactive)


@ap_bp.route('/vendors/new', methods=['GET', 'POST'])
@login_required
@treasurer_required
def vendor_new():
    if request.method == 'POST':
        try:
            vendor = Vendor(
                organization_id=current_user.organization_id,
                name=request.form['name'],
                contact_name=request.form.get('contact_name'),
                email=request.form.get('email'),
                phone=request.form.get('phone'),
                address=request.form.get('address'),
                city=request.form.get('city'),
                state=request.form.get('state'),
                zip_code=request.form.get('zip_code'),
                payment_terms=request.form.get('payment_terms', 'Net30'),
                is_1099=request.form.get('is_1099') == 'on',
                notes=request.form.get('notes'),
            )
            db.session.add(vendor)
            db.session.commit()
            flash('Vendor created successfully.', 'success')
            return redirect(url_for('ap.vendors'))
        except Exception as e:
            db.session.rollback()
            flash(f'Error creating vendor: {e}', 'error')

    return render_template('ap/vendor_form.html', vendor=None)


@ap_bp.route('/vendors/<int:id>/edit', methods=['GET', 'POST'])
@login_required
@treasurer_required
def vendor_edit(id):
    vendor = Vendor.query.filter_by(
        id=id, organization_id=current_user.organization_id
    ).first_or_404()

    if request.method == 'POST':
        try:
            vendor.name          = request.form['name']
            vendor.contact_name  = request.form.get('contact_name')
            vendor.email         = request.form.get('email')
            vendor.phone         = request.form.get('phone')
            vendor.address       = request.form.get('address')
            vendor.city          = request.form.get('city')
            vendor.state         = request.form.get('state')
            vendor.zip_code      = request.form.get('zip_code')
            vendor.payment_terms = request.form.get('payment_terms', 'Net30')
            vendor.is_1099       = request.form.get('is_1099') == 'on'
            vendor.active        = request.form.get('active') == 'on'
            vendor.notes         = request.form.get('notes')
            db.session.commit()
            flash('Vendor updated successfully.', 'success')
            return redirect(url_for('ap.vendors'))
        except Exception as e:
            db.session.rollback()
            flash(f'Error updating vendor: {e}', 'error')

    return render_template('ap/vendor_form.html', vendor=vendor)


# ==================== INVOICES ====================

@ap_bp.route('/')
@login_required
@treasurer_required
def invoices():
    status_filter = request.args.get('status', 'Open')
    vendor_filter = request.args.get('vendor_id', 0, type=int)

    query = Invoice.query.filter_by(organization_id=current_user.organization_id)
    if status_filter and status_filter != 'All':
        query = query.filter_by(status=status_filter)
    if vendor_filter:
        query = query.filter_by(vendor_id=vendor_filter)

    vendors = Vendor.query.filter_by(
        organization_id=current_user.organization_id, active=True
    ).order_by(Vendor.name).all()

    return render_template('ap/invoices.html',
                           invoices=query.order_by(Invoice.due_date.asc()).all(),
                           vendors=vendors,
                           status_filter=status_filter,
                           vendor_filter=vendor_filter)


@ap_bp.route('/invoices/new', methods=['GET', 'POST'])
@login_required
@treasurer_required
def invoice_new():
    if request.method == 'POST':
        try:
            gl_account_id = int(request.form['gl_account_id'])
            gl_account = ChartOfAccounts.query.get_or_404(gl_account_id)

            invoice = create_invoice(
                organization_id=current_user.organization_id,
                vendor_id=int(request.form['vendor_id']),
                project_id=int(request.form['project_id']),
                gl_account_number=gl_account.account_number,
                gl_account_id=gl_account_id,
                invoice_number=request.form.get('invoice_number', ''),
                invoice_date=datetime.strptime(request.form['invoice_date'], '%Y-%m-%d').date(),
                due_date=datetime.strptime(request.form['due_date'], '%Y-%m-%d').date(),
                amount=Decimal(request.form['amount']),
                notes=request.form.get('notes', ''),
                created_by=current_user.id,
            )
            flash(f'Invoice entered and journal entry posted.', 'success')
            return redirect(url_for('ap.invoices'))
        except APServiceError as e:
            db.session.rollback()
            flash(str(e), 'error')
        except Exception as e:
            db.session.rollback()
            flash(f'Unexpected error: {e}', 'error')

    vendors = Vendor.query.filter_by(
        organization_id=current_user.organization_id, active=True
    ).order_by(Vendor.name).all()
    projects = Project.query.filter_by(
        organization_id=current_user.organization_id, status='Active'
    ).order_by(Project.name).all()
    expense_accounts = ChartOfAccounts.query.filter_by(
        account_type='Expense', active=True
    ).order_by(ChartOfAccounts.account_number).all()

    return render_template('ap/invoice_form.html',
                           vendors=vendors,
                           projects=projects,
                           expense_accounts=expense_accounts,
                           today=date.today().strftime('%Y-%m-%d'))


@ap_bp.route('/invoices/<int:id>/pay', methods=['GET', 'POST'])
@login_required
@treasurer_required
def invoice_pay(id):
    invoice = Invoice.query.filter_by(
        id=id, organization_id=current_user.organization_id
    ).first_or_404()

    if request.method == 'POST':
        try:
            record_payment(
                invoice=invoice,
                payment_amount=Decimal(request.form['amount']),
                payment_date=datetime.strptime(request.form['payment_date'], '%Y-%m-%d').date(),
                reference_number=request.form.get('reference_number', ''),
                created_by=current_user.id,
            )
            flash('Payment recorded and journal entry posted.', 'success')
            return redirect(url_for('ap.invoices'))
        except APServiceError as e:
            db.session.rollback()
            flash(str(e), 'error')
        except Exception as e:
            db.session.rollback()
            flash(f'Unexpected error: {e}', 'error')

    return render_template('ap/invoice_pay.html',
                           invoice=invoice,
                           today=date.today().strftime('%Y-%m-%d'))


@ap_bp.route('/invoices/<int:id>/void', methods=['POST'])
@login_required
@treasurer_required
def invoice_void(id):
    invoice = Invoice.query.filter_by(
        id=id, organization_id=current_user.organization_id
    ).first_or_404()
    try:
        void_invoice(invoice)
        flash('Invoice voided.', 'success')
    except APServiceError as e:
        flash(str(e), 'error')
    return redirect(url_for('ap.invoices'))


# ==================== AGING REPORT ====================

@ap_bp.route('/aging')
@login_required
@treasurer_required
def aging():
    open_invoices = Invoice.query.filter(
        Invoice.organization_id == current_user.organization_id,
        Invoice.status.in_(['Open', 'Partial'])
    ).order_by(Invoice.due_date.asc()).all()

    buckets = {'Current': [], '1-30': [], '31-60': [], '61-90': [], '90+': []}
    totals  = {k: Decimal('0.00') for k in buckets}

    for inv in open_invoices:
        b = inv.aging_bucket
        buckets[b].append(inv)
        totals[b] += inv.amount_due

    return render_template('ap/aging.html',
                           buckets=buckets,
                           totals=totals,
                           grand_total=sum(totals.values()),
                           as_of=date.today())


# ==================== 1099 REPORT ====================

@ap_bp.route('/1099')
@login_required
@treasurer_required
def report_1099():
    year = request.args.get('year', date.today().year, type=int)

    vendors_1099 = Vendor.query.filter_by(
        organization_id=current_user.organization_id, is_1099=True
    ).order_by(Vendor.name).all()

    results = []
    for vendor in vendors_1099:
        paid = db.session.query(func.sum(InvoicePayment.amount))\
            .join(Invoice, InvoicePayment.invoice_id == Invoice.id)\
            .filter(
                Invoice.vendor_id == vendor.id,
                func.extract('year', InvoicePayment.payment_date) == year
            ).scalar() or Decimal('0.00')
        results.append({'vendor': vendor, 'total_paid': paid})

    return render_template('ap/1099.html', results=results, year=year)

"""
Chart of Accounts Management Blueprint
Handles all chart of accounts operations including CRUD and filtering
"""

from flask import Blueprint, render_template, request, redirect, url_for, flash
from flask_login import login_required, current_user
from models import db, ChartOfAccounts
from functools import wraps

# Create the blueprint
chart_of_accounts_bp = Blueprint('chart_of_accounts', __name__, url_prefix='/chart-of-accounts')


# Decorator to require Admin role
def admin_required(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        if current_user.role not in ['Admin']:
            flash('You do not have permission to access this page.', 'danger')
            return redirect(url_for('index'))
        return f(*args, **kwargs)
    return decorated_function


# ==================== CHART OF ACCOUNTS CRUD ====================

@chart_of_accounts_bp.route('/')
@login_required
def list():
    """List all chart of accounts with filtering"""
    # Get filter parameters
    search_query = request.args.get('search', '').strip()
    account_type_filter = request.args.get('type', '').strip()
    show_inactive = request.args.get('show_inactive', '').lower() == 'true'
    
    # Build query
    query = ChartOfAccounts.query
    
    # Apply filters
    if search_query:
        query = query.filter(
            (ChartOfAccounts.account_number.ilike(f'%{search_query}%')) |
            (ChartOfAccounts.account_name.ilike(f'%{search_query}%'))
        )
    
    if account_type_filter:
        query = query.filter(ChartOfAccounts.account_type == account_type_filter)
    
    if not show_inactive:
        query = query.filter(ChartOfAccounts.active == True)
    
    # Order by account number
    accounts = query.order_by(ChartOfAccounts.account_number).all()
    
    # Get all account types for the filter dropdown
    account_types = db.session.query(ChartOfAccounts.account_type).distinct().all()
    account_types = [t[0] for t in account_types if t[0]]
    account_types.sort()
    
    return render_template('chart_of_accounts.html',
                         accounts=accounts,
                         account_types=account_types,
                         account_type_filter=account_type_filter,
                         search_query=search_query,
                         show_inactive=show_inactive)


@chart_of_accounts_bp.route('/new', methods=['GET', 'POST'])
@login_required
@admin_required
def new():
    """Create new chart of accounts entry"""
    if request.method == 'POST':
        try:
            # Validate account number is unique
            existing = ChartOfAccounts.query.filter_by(
                account_number=request.form['account_number']
            ).first()
            if existing:
                flash('Account number already exists', 'error')
                return redirect(url_for('chart_of_accounts.new'))
            
            account = ChartOfAccounts(
                account_number=request.form['account_number'],
                account_name=request.form['account_name'],
                account_type=request.form['account_type'],
                account_subtype=request.form.get('account_subtype'),
                normal_balance=request.form['normal_balance'],
                description=request.form.get('description'),
                parent_account_id=request.form.get('parent_account_id') or None,
                active=True
            )
            
            db.session.add(account)
            db.session.commit()
            flash('Account created successfully!', 'success')
            return redirect(url_for('chart_of_accounts.list'))
        except Exception as e:
            flash(f'Error creating account: {str(e)}', 'error')
            db.session.rollback()
    
    # Get parent accounts for dropdown (only active accounts)
    parent_accounts = ChartOfAccounts.query.filter_by(active=True).order_by(
        ChartOfAccounts.account_number
    ).all()
    
    return render_template('chart_of_accounts_form.html',
                         account=None,
                         parent_accounts=parent_accounts)


@chart_of_accounts_bp.route('/<int:id>/edit', methods=['GET', 'POST'])
@login_required
@admin_required
def edit(id):
    """Edit existing chart of accounts entry"""
    account = ChartOfAccounts.query.get_or_404(id)
    
    if request.method == 'POST':
        try:
            # Check if account number is being changed and if new number already exists
            if request.form['account_number'] != account.account_number:
                existing = ChartOfAccounts.query.filter_by(
                    account_number=request.form['account_number']
                ).first()
                if existing:
                    flash('Account number already exists', 'error')
                    return redirect(url_for('chart_of_accounts.edit', id=id))
            
            account.account_number = request.form['account_number']
            account.account_name = request.form['account_name']
            account.account_type = request.form['account_type']
            account.account_subtype = request.form.get('account_subtype')
            account.normal_balance = request.form['normal_balance']
            account.description = request.form.get('description')
            account.parent_account_id = request.form.get('parent_account_id') or None
            
            db.session.commit()
            flash('Account updated successfully!', 'success')
            return redirect(url_for('chart_of_accounts.list'))
        except Exception as e:
            flash(f'Error updating account: {str(e)}', 'error')
            db.session.rollback()
    
    # Get parent accounts for dropdown (exclude current account to prevent circular references)
    parent_accounts = ChartOfAccounts.query.filter(
        ChartOfAccounts.id != id,
        ChartOfAccounts.active == True
    ).order_by(ChartOfAccounts.account_number).all()
    
    return render_template('chart_of_accounts_form.html',
                         account=account,
                         parent_accounts=parent_accounts)


@chart_of_accounts_bp.route('/<int:id>/toggle-active', methods=['POST'])
@login_required
@admin_required
def toggle_active(id):
    """Toggle active status of an account"""
    try:
        account = ChartOfAccounts.query.get_or_404(id)
        account.active = not account.active
        db.session.commit()
        
        status = 'activated' if account.active else 'deactivated'
        flash(f'Account {status} successfully!', 'success')
    except Exception as e:
        flash(f'Error toggling account status: {str(e)}', 'error')
        db.session.rollback()
    
    return redirect(url_for('chart_of_accounts.list'))

"""
Member Management Blueprint
Handles all member-related routes including CRUD, import, export, and annual dues
"""

import csv
import io
from datetime import datetime, date
from decimal import Decimal
from functools import wraps

from flask import Blueprint, render_template, request, redirect, url_for, flash, make_response, jsonify
from flask_login import login_required, current_user

from models import db, Member, MemberDuesPayment, Organization, Project, ChartOfAccounts, JournalEntry, JournalEntryLine

# Create the blueprint
members_bp = Blueprint('members', __name__, url_prefix='/members')


# Decorator to require Admin or Treasurer role
def admin_or_treasurer_required(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        if current_user.role not in ['Admin', 'Treasurer']:
            flash('You do not have permission to access this page.', 'danger')
            return redirect(url_for('index'))
        return f(*args, **kwargs)
    return decorated_function


# Decorator for dues management (Admin, Treasurer, Membership Coordinator)
def dues_access_required(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        if current_user.role not in ['Admin', 'Treasurer', 'Membership Coordinator']:
            flash('You do not have permission to manage dues.', 'danger')
            return redirect(url_for('index'))
