from sqlalchemy import func
from functools import wraps

# Create the blueprint
users_bp = Blueprint('users', __name__, url_prefix='/users')


# Decorator to require Admin role
def admin_required(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        if current_user.role != 'Admin':
            flash('You must be an administrator to access this page.', 'danger')
            return redirect(url_for('index'))
        return f(*args, **kwargs)
    return decorated_function


# ==================== USER CRUD ====================

@users_bp.route('/')
@login_required
@admin_required
def list():
    """List all users in the current organization"""
    users = User.query.filter_by(
        organization_id=current_user.organization_id
    ).order_by(User.username).all()
    return render_template('users.html', users=users)


@users_bp.route('/new', methods=['GET', 'POST'])
@login_required
@admin_required
def new():
    """Create new user"""
    # Compute available years for selection
    from models import JournalEntry, Project

    # Use extract for PostgreSQL/MySQL, strftime for SQLite
    dialect = db.engine.dialect.name
    if dialect == 'postgresql' or dialect == 'mysql':
        years_q = db.session.query(func.extract('year', JournalEntry.entry_date).label('year'))\
            .join(Project, JournalEntry.project_id == Project.id)\
            .filter(Project.organization_id == current_user.organization_id, JournalEntry.status == 'Posted')\
            .distinct().order_by(func.extract('year', JournalEntry.entry_date).desc()).all()
        years = [int(int(y[0])) for y in years_q if y[0]]
    else:
        years_q = db.session.query(func.strftime('%Y', JournalEntry.entry_date).label('year'))\
            .join(Project, JournalEntry.project_id == Project.id)\
            .filter(Project.organization_id == current_user.organization_id, JournalEntry.status == 'Posted')\
            .distinct().order_by(func.strftime('%Y', JournalEntry.entry_date).desc()).all()
        years = [int(y[0]) for y in years_q if y[0]]

    if request.method == 'POST':
        try:
            # Validate username uniqueness
            existing_user = User.query.filter_by(username=request.form['username']).first()
            if existing_user:
                flash('Username already exists. Please choose a different username.', 'danger')
                return redirect(request.url)

            # Validate email uniqueness
            if request.form.get('email'):
                existing_email = User.query.filter_by(email=request.form['email']).first()
                if existing_email:
                    flash('Email already exists. Please use a different email.', 'danger')
                    return redirect(request.url)

            # Validate password
            password = request.form.get('password')
            password_confirm = request.form.get('password_confirm')

            if not password or len(password) < 8:
                flash('Password must be at least 8 characters long.', 'danger')
                return redirect(request.url)

            if password != password_confirm:
                flash('Passwords do not match.', 'danger')
                return redirect(request.url)

            # Create user
            user = User(
                username=request.form['username'],
                email=request.form['email'],
                role=request.form['role'],
                organization_id=current_user.organization_id,
                active=True
            )
            user.set_password(password)
            # Set default_report_year if provided
            val = request.form.get('default_report_year')
            user.default_report_year = int(val) if val else None

            db.session.add(user)
            db.session.commit()

            flash(f'User "{user.username}" created successfully!', 'success')
            return redirect(url_for('users.list'))

        except Exception as e:
            flash(f'Error creating user: {str(e)}', 'danger')
            db.session.rollback()

    return render_template('user_form.html', user=None, years=years)


@users_bp.route('/<int:id>/edit', methods=['GET', 'POST'])
@login_required
@admin_required
def edit(id):
    """Edit existing user"""
    user = User.query.get_or_404(id)

    # Verify user belongs to same organization
    if user.organization_id != current_user.organization_id:
        flash('Permission denied.', 'danger')
        return redirect(url_for('users.list'))

    # Compute available years
    from models import JournalEntry, Project

    # Use extract for PostgreSQL/MySQL, strftime for SQLite
    dialect = db.engine.dialect.name
    if dialect == 'postgresql' or dialect == 'mysql':
        years_q = db.session.query(func.extract('year', JournalEntry.entry_date).label('year'))\
            .join(Project, JournalEntry.project_id == Project.id)\
            .filter(Project.organization_id == current_user.organization_id, JournalEntry.status == 'Posted')\
            .distinct().order_by(func.extract('year', JournalEntry.entry_date).desc()).all()
        years = [int(int(y[0])) for y in years_q if y[0]]
    else:
        years_q = db.session.query(func.strftime('%Y', JournalEntry.entry_date).label('year'))\
            .join(Project, JournalEntry.project_id == Project.id)\
            .filter(Project.organization_id == current_user.organization_id, JournalEntry.status == 'Posted')\
            .distinct().order_by(func.strftime('%Y', JournalEntry.entry_date).desc()).all()
        years = [int(y[0]) for y in years_q if y[0]]

    if request.method == 'POST':
        try:
            # Check if username changed and is unique
            if user.username != request.form['username']:
                existing_user = User.query.filter_by(username=request.form['username']).first()
                if existing_user:
                    flash('Username already exists. Please choose a different username.', 'danger')
                    return redirect(request.url)

            # Check if email changed and is unique
