#!/usr/bin/env pwsh
# Restart the application's PostgreSQL database container

Write-Host "Checking for existing kofc-postgres container..."
$existing = docker ps -a --format "{{.Names}}" | Select-String "kofc-postgres"

if ($existing) {
    Write-Host "Found existing kofc-postgres container, removing it..."
    docker stop kofc-postgres 2>$null
    docker rm kofc-postgres 2>$null
}

Write-Host "Starting kofc-postgres container..."
docker run `
    --name kofc-postgres `
    -e POSTGRES_PASSWORD=dev123 `
    -e POSTGRES_DB=kofc_accounting `
    -p 5432:5432 `
    -d postgres:15-alpine

Write-Host "Waiting for database to be ready..."
Start-Sleep -Seconds 3

Write-Host "Checking database connection..."
$counter = 0
while ($counter -lt 10) {
    try {
        docker exec kofc-postgres pg_isready -U postgres | Out-Null
        if ($?) {
            Write-Host "✓ Database is ready!"
            break
        }
    } catch {
        # Silently retry
    }
    $counter++
    if ($counter -lt 10) {
        Start-Sleep -Seconds 1
    }
}

if ($counter -eq 10) {
    Write-Host "✗ Database did not start in time"
    exit 1
}

Write-Host "`nApplication database (kofc-postgres) is ready!"
Write-Host "Connection: postgresql://postgres:dev123@localhost:5432/kofc_accounting"

/*
 * BRANDING.CSS
 * CARES Official Color Scheme
 *
 * This file contains the brand colors and styling for the application.
 * To rebrand for another organization, simply update the CSS variables
 * in the :root section below.
 *
 * CARES Colors:
 * - Forest Green: #1A6B3C  - Primary brand color
 * - Gold:         #F0A500  - Secondary accent
 * - Amber:        #DC6B2F  - Call-to-action, warnings
 * - White:        #FFFFFF  - Background, text on dark
 */

:root {
    /* Primary Brand Colors */
    --brand-primary: #1A6B3C;        /* Forest Green - Primary brand color */
    --brand-secondary: #F0A500;      /* Gold - Secondary accent */
    --brand-accent: #DC6B2F;         /* Amber - Call-to-action, alerts */
    --brand-light: #FFFFFF;          /* White - Background, text on dark */

    /* Extended Palette (derived from primary colors) */
    --brand-primary-light: #2E8A52;  /* Mid green for hovers */
    --brand-primary-dark: #0F4022;   /* Dark green for emphasis */
    --brand-secondary-light: #F5BC3C; /* Light gold for hovers */
    --brand-secondary-dark: #C88700; /* Dark gold */

    /* Neutral Colors */
    --gray-100: #F8F9FA;
    --gray-200: #E9ECEF;
    --gray-300: #DEE2E6;
    --gray-400: #CED4DA;
    --gray-500: #ADB5BD;
    --gray-600: #6C757D;
    --gray-700: #495057;
    --gray-800: #343A40;
    --gray-900: #212529;

    /* Semantic Colors */
    --success: #28A745;
    --info: #17A2B8;
    --warning: #FFC107;
    --danger: #DC3545;

    /* Typography */
    --font-family-primary: 'Arial', 'Helvetica Neue', sans-serif;
    --font-family-heading: 'Georgia', 'Times New Roman', serif;

    /* Bootstrap variable overrides — ensures text-primary, btn-primary etc follow our green */
    --bs-primary: #1A6B3C;
    --bs-primary-rgb: 26, 107, 60;
    --bs-link-color: #1A6B3C;
    --bs-link-hover-color: #2E8A52;
}

/* Override Bootstrap text/bg utility classes */
.text-primary {
    color: var(--brand-primary) !important;
}

.bg-primary {
    background-color: var(--brand-primary) !important;
}

/* ============================================
   PRIMARY NAVIGATION & HEADER
   ============================================ */
.navbar-brand {
    color: var(--brand-light) !important;
    font-weight: bold;
}

