}

.alert-dismissible .btn-close {
    padding: 0.875rem 1rem;
}

/* ============================================
   LOADING STATES
   ============================================ */
.spinner-border-sm {
    width: 1rem;
    height: 1rem;
    border-width: 0.15rem;
}

/* ============================================
   EMPTY STATES
   ============================================ */
.empty-state {
    text-align: center;
    padding: 4rem 2rem;
    color: #6b7280;
}

.empty-state-icon {
    font-size: 4rem;
    color: #d1d5db;
    margin-bottom: 1rem;
}

.empty-state-title {
    font-size: 1.25rem;
    font-weight: 600;
    color: #374151;
    margin-bottom: 0.5rem;
}

.empty-state-description {
    color: #6b7280;
    margin-bottom: 1.5rem;
}

/* ============================================
   MOBILE RESPONSIVE
   ============================================ */
@media (max-width: 768px) {
    .sidebar {
        transform: translateX(-100%);
    }

    .sidebar.show {
        transform: translateX(0);
    }

    .main-content {
        margin-left: 0;
        width: 100%;
        padding: 1rem;
    }

    .top-header {
        padding: 0.75rem 1rem;
    }

    .stat-card {
        margin-bottom: 1rem;
    }

    .page-title {
        font-size: 1.5rem;
    }

    .table-container {
        overflow-x: auto;
    }

    .form-container {
        padding: 1.5rem;
    }

    /* Mobile: Sections expand on click, not hover */
    .collapsible-section:hover .sidebar-section-content {
        max-height: 0;
        opacity: 0;
    }

    .collapsible-section:hover .chevron-icon {
        transform: none;
    }
}

@media (max-width: 992px) {
    /* Tablet and mobile: Click to toggle sections */
    .collapsible-section:hover .sidebar-section-content {
        max-height: 0;
        opacity: 0;
    }

    .collapsible-section:hover .chevron-icon {
        transform: none;
    }

    /* Active sections still expand */
    .collapsible-section.active .sidebar-section-content {
        max-height: 500px;
        opacity: 1;
    }

    .collapsible-section.active .chevron-icon {
        transform: rotate(90deg);
    }
}

@media (max-width: 576px) {
    .main-content {
        padding: 0.75rem;
    }

    .card-body {
        padding: 1rem;
    }

    .btn {
        width: 100%;
        margin-bottom: 0.5rem;
    }

    .page-actions {
        flex-direction: column;
        width: 100%;
    }
}

/* ============================================
   UTILITIES
   ============================================ */
.text-primary {
    color: var(--brand-primary) !important;
}

.text-secondary {
    color: var(--brand-secondary) !important;
}

.bg-light-primary {
    background-color: #f0faf4 !important;
}

.bg-light-secondary {
