    gap: 1rem;
}

/* Spacing Utilities */
.gap-1 { gap: 0.25rem; }
.gap-2 { gap: 0.5rem; }
.gap-3 { gap: 1rem; }
.gap-4 { gap: 1.5rem; }
.gap-5 { gap: 3rem; }

/* Compact spacing for data-dense pages */
.compact-spacing .mb-3 { margin-bottom: 0.75rem !important; }
.compact-spacing .mb-4 { margin-bottom: 1rem !important; }
.compact-spacing .py-3 { padding-top: 0.75rem !important; padding-bottom: 0.75rem !important; }

/* ============================================
   FOOTER
   ============================================ */
.app-footer {
    background-color: #ffffff;
    border-top: 1px solid #e5e7eb;
    padding: 1rem 2rem;
