{% extends "base.html" %}

{% block title %}Change Password{% endblock %}

{% block content %}
<div class="d-flex justify-content-between flex-wrap flex-md-nowrap align-items-center pt-3 pb-2 mb-3 border-bottom">
    <h1 class="h2">Change Password</h1>
</div>

<div class="row justify-content-center">
    <div class="col-md-6">
        <div class="card">
            <div class="card-header">
                <h5 class="mb-0">
                    <i class="bi bi-key"></i> 
                    {% if current_user.id == user.id %}
                    Change Your Password
                    {% else %}
                    Change Password for {{ user.username }}
                    {% endif %}
                </h5>
            </div>
            <div class="card-body">
                <form method="POST">
                    {% if current_user.id == user.id %}
                    <div class="mb-3">
                        <label for="current_password" class="form-label">Current Password *</label>
                        <input type="password" 
                               class="form-control" 
                               id="current_password" 
                               name="current_password" 
                               required
                               autofocus>
                        <small class="text-muted">Enter your current password to verify your identity</small>
                    </div>
                    <hr class="my-4">
                    {% else %}
                    <div class="alert alert-info">
                        <i class="bi bi-info-circle"></i> You are changing the password for user: <strong>{{ user.username }}</strong>
                    </div>
                    {% endif %}

                    <div class="mb-3">
                        <label for="new_password" class="form-label">New Password *</label>
                        <input type="password" 
                               class="form-control" 
                               id="new_password" 
                               name="new_password" 
                               required
                               minlength="8">
                        <small class="text-muted">Minimum 8 characters</small>
                        <div class="mt-2">
                            <small id="password-strength" class="text-muted"></small>
                        </div>
                    </div>

                    <div class="mb-3">
                        <label for="confirm_password" class="form-label">Confirm New Password *</label>
                        <input type="password" 
                               class="form-control" 
                               id="confirm_password" 
                               name="confirm_password" 
                               required
                               minlength="8">
                        <div class="invalid-feedback" id="password-match-feedback">
                            Passwords do not match
                        </div>
                    </div>

                    <div class="alert alert-warning">
                        <i class="bi bi-exclamation-triangle"></i> 
                        <strong>Security Note:</strong> 
                        {% if current_user.id == user.id %}
                        After changing your password, you will remain logged in on this device.
                        {% else %}
                        The user will need to use their new password on next login.
                        {% endif %}
                    </div>

                    <div class="d-grid gap-2 d-md-flex justify-content-md-end">
                        <a href="{{ url_for('users.list') if current_user.role == 'Admin' and current_user.id != user.id else url_for('index') }}" 
                           class="btn btn-secondary">Cancel</a>
                        <button type="submit" class="btn btn-primary">
                            <i class="bi bi-check-circle"></i> Change Password
                        </button>
                    </div>
                </form>
            </div>
        </div>

        <div class="card mt-3">
            <div class="card-header">
                <i class="bi bi-shield-lock"></i> Password Security Tips
            </div>
            <div class="card-body">
                <ul class="small mb-0">
                    <li>Use a unique password for this account</li>
                    <li>Mix uppercase, lowercase, numbers, and symbols</li>
                    <li>Avoid personal information (names, birthdays, etc.)</li>
                    <li>Don't reuse passwords from other websites</li>
                    <li>Consider using a password manager</li>
                    <li>Change your password every 90 days</li>
                </ul>
            </div>
        </div>
    </div>
</div>

<script>
// Password strength indicator
document.getElementById('new_password').addEventListener('input', function() {
    const password = this.value;
    const strengthIndicator = document.getElementById('password-strength');

    if (password.length === 0) {
        strengthIndicator.textContent = '';
        return;
    }

    let strength = 0;
    const checks = [
        password.length >= 8,
        password.length >= 12,
        /[a-z]/.test(password),
        /[A-Z]/.test(password),
        /[0-9]/.test(password),
        /[^a-zA-Z0-9]/.test(password)
    ];

    strength = checks.filter(Boolean).length;

    const labels = [
        { text: 'Very Weak', class: 'text-danger' },
        { text: 'Weak', class: 'text-danger' },
        { text: 'Fair', class: 'text-warning' },
        { text: 'Good', class: 'text-info' },
        { text: 'Strong', class: 'text-success' },
        { text: 'Very Strong', class: 'text-success fw-bold' }
    ];

    const level = Math.min(strength, labels.length - 1);
    strengthIndicator.textContent = `Password strength: ${labels[level].text}`;
    strengthIndicator.className = labels[level].class;
});

// Password match validation
document.getElementById('confirm_password').addEventListener('input', function() {
    const password = document.getElementById('new_password').value;
    const confirm = this.value;
    const feedback = document.getElementById('password-match-feedback');

    if (confirm && password !== confirm) {
        this.classList.add('is-invalid');
        this.setCustomValidity('Passwords do not match');
    } else {
        this.classList.remove('is-invalid');
        this.setCustomValidity('');
    }
});

// Show/hide password toggle (optional enhancement)
function togglePasswordVisibility(inputId) {
    const input = document.getElementById(inputId);
    input.type = input.type === 'password' ? 'text' : 'password';
}
</script>
{% endblock %}

{% extends "base.html" %}

{% block title %}Annual Dues Roster {{ year }} - {{ APP_NAME }}{% endblock %}

{% block content %}
<div class="d-flex justify-content-between flex-wrap flex-md-nowrap align-items-center pt-3 pb-2 mb-3 border-bottom">
    <h1 class="h2"><i class="bi bi-cash-coin"></i> Annual Dues Roster</h1>
    <div class="btn-toolbar mb-2 mb-md-0 gap-2">
        <!-- Year selector -->
        <form method="GET" action="{{ url_for('members.dues_roster') }}" class="d-flex align-items-center gap-2">
            <label class="mb-0 fw-semibold">Year:</label>
            <select name="year" class="form-select form-select-sm" onchange="this.form.submit()" style="width:auto;">
                {% for y in year_range %}
                <option value="{{ y }}" {% if y == year %}selected{% endif %}>{{ y }}</option>
                {% endfor %}
            </select>
        </form>
    </div>
</div>

<!-- Summary bar -->
<div class="row g-3 mb-4">
    <div class="col-sm-4">
        <div class="card text-center border-success">
            <div class="card-body py-2">
                <div class="fs-4 fw-bold text-success" id="paid-count">{{ paid_count }}</div>
                <div class="small text-muted">Paid</div>
            </div>
        </div>
    </div>
    <div class="col-sm-4">
        <div class="card text-center">
            <div class="card-body py-2">
                <div class="fs-4 fw-bold text-secondary">{{ total_active - paid_count }}</div>
                <div class="small text-muted">Unpaid</div>
            </div>
        </div>
    </div>
    <div class="col-sm-4">
        <div class="card text-center">
            <div class="card-body py-2">
                <div class="fs-4 fw-bold">{{ total_active }}</div>
                <div class="small text-muted">Active Members</div>
            </div>
        </div>
    </div>
</div>

<!-- Roster table -->
<div class="card">
    <div class="card-body p-0">
        <div class="table-responsive">
            <table class="table table-hover mb-0">
                <thead class="table-light">
                    <tr>
                        <th>Member</th>
                        <th class="text-center">Dues Paid</th>
                        <th class="text-center">Paid Date</th>
                        <th class="text-center">Include in Transaction</th>
                        <th class="text-center">GL Status</th>
                    </tr>
                </thead>
                <tbody>
                    {% for member in members %}
                    {% set dues = dues_map.get(member.id) %}
                    {% set is_paid = dues and dues.paid_date %}
                    {% set has_je = dues and dues.journal_entry_id %}
                    <tr id="row-{{ member.id }}">
                        <td class="align-middle fw-semibold">{{ member.name }}</td>

                        <!-- Dues Paid checkbox -->
                        <td class="text-center align-middle">
                            <div class="form-check d-flex justify-content-center">
                                <input class="form-check-input dues-paid-cb"
                                       type="checkbox"
                                       data-member-id="{{ member.id }}"
                                       data-year="{{ year }}"
                                       {% if is_paid %}checked{% endif %}
                                       {% if has_je %}disabled title="Transaction already posted"{% endif %}>
                            </div>
                        </td>

                        <!-- Paid date -->
                        <td class="text-center align-middle small text-muted" id="paid-date-{{ member.id }}">
                            {% if is_paid %}
                                {{ dues.paid_date.strftime('%Y-%m-%d') }}
                            {% else %}
                                —
                            {% endif %}
                        </td>

                        <!-- Include in Transaction toggle -->
                        <td class="text-center align-middle">
                            {% if is_paid %}
                            <div class="form-check form-switch d-flex justify-content-center">
                                <input class="form-check-input include-txn-cb"
                                       type="checkbox"
                                       role="switch"
                                       data-member-id="{{ member.id }}"
                                       data-year="{{ year }}"
                                       {% if not dues or dues.include_in_transaction %}checked{% endif %}
                                       {% if has_je %}disabled title="Transaction already posted"{% endif %}>
                            </div>
                            {% else %}
                            <span class="text-muted small">—</span>
                            {% endif %}
                        </td>

                        <!-- GL status -->
                        <td class="text-center align-middle">
                            {% if has_je %}
                                <span class="badge bg-success">
                                    <i class="bi bi-check-circle"></i> Posted (JE #{{ dues.journal_entry_id }})
                                </span>
                            {% elif is_paid and dues.include_in_transaction %}
                                <span class="badge bg-warning text-dark">
                                    <i class="bi bi-clock"></i> Pending
                                </span>
                            {% elif is_paid %}
                                <span class="badge bg-secondary">
                                    <i class="bi bi-dash-circle"></i> Excluded
                                </span>
                            {% else %}
                                <span class="text-muted small">—</span>
                            {% endif %}
                        </td>
                    </tr>
                    {% endfor %}
                </tbody>
            </table>
        </div>
    </div>
</div>

{% if current_user.role in ["Admin", "Treasurer"] %}
<form method="POST" action="{{ url_for('members.dues_create_transactions') }}" onsubmit="return confirmPost()" class="mt-3 text-end">
    <input type="hidden" name="year" value="{{ year }}">
    <span class="text-muted small me-3">
        JE: Dr Cash (1010) / Cr Membership Dues (4110) &middot; Project: {{ dues_project.name }}
        {% if org.dues_amount %} &middot; ${{ "%.2f"|format(org.dues_amount) }}/member{% endif %}
    </span>
    <button type="submit" class="btn btn-primary">
        <i class="bi bi-journal-plus"></i> Submit
    </button>
</form>
{% endif %}

{% endblock %}

{% block scripts %}
<script>
const YEAR = {{ year }};

function confirmPost() {
    const rows = document.querySelectorAll('tbody tr');
    let eligible = 0;
    rows.forEach(row => {
        const paid = row.querySelector('.dues-paid-cb');
        const incl = row.querySelector('.include-txn-cb');
        if (paid && paid.checked && !paid.disabled && incl && incl.checked && !incl.disabled) {
            eligible++;
        }
    });
    if (eligible === 0) {
        alert('No eligible members found. Mark members as paid and enable Include in Transaction.');
        return false;
    }
    return confirm('Post dues transactions for ' + eligible + ' member(s)? One GL entry will be created per member.');
}

// ── Dues paid checkbox ──────────────────────────────────────────
document.querySelectorAll('.dues-paid-cb').forEach(cb => {
    cb.addEventListener('change', function () {
        const memberId = this.dataset.memberId;
        const paid = this.checked;

        fetch('{{ url_for("members.dues_toggle") }}', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({member_id: parseInt(memberId), year: YEAR, paid: paid})
        })
        .then(r => r.json())
        .then(data => {
            if (data.error) {
                alert('Error: ' + data.error);
                this.checked = !paid;  // revert
                return;
            }
            // Update paid date cell
            const dateCell = document.getElementById('paid-date-' + memberId);
            if (dateCell) dateCell.textContent = data.paid_date || '—';

            // Show/hide the include toggle
            const row = document.getElementById('row-' + memberId);
            if (row) {
                const inclCell = row.querySelector('td:nth-child(4)');
                const glCell = row.querySelector('td:nth-child(5)');
                if (paid) {
                    inclCell.innerHTML = `
                        <div class="form-check form-switch d-flex justify-content-center">
                            <input class="form-check-input include-txn-cb" type="checkbox" role="switch"
                                   data-member-id="${memberId}" data-year="${YEAR}" checked>
                        </div>`;
                    glCell.innerHTML = '<span class="badge bg-warning text-dark"><i class="bi bi-clock"></i> Pending</span>';
                    // Re-attach listener on new element
                    inclCell.querySelector('.include-txn-cb').addEventListener('change', toggleTransaction);
                } else {
                    inclCell.innerHTML = '<span class="text-muted small">—</span>';
                    glCell.innerHTML = '<span class="text-muted small">—</span>';
                }
            }
            // Update summary counts
            updateSummary();
        })
        .catch(err => {
            alert('Network error. Please try again.');
            this.checked = !paid;
        });
    });
});

// ── Include in transaction toggle ──────────────────────────────
function toggleTransaction() {
    const memberId = this.dataset.memberId;
    const include = this.checked;

    fetch('{{ url_for("members.dues_toggle_transaction") }}', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({member_id: parseInt(memberId), year: YEAR, include: include})
    })
    .then(r => r.json())
    .then(data => {
        if (data.error) {
            alert('Error: ' + data.error);
            this.checked = !include;  // revert
            return;
        }
        // Update GL status badge
        const row = document.getElementById('row-' + memberId);
        if (row) {
            const glCell = row.querySelector('td:nth-child(5)');
            if (include) {
                glCell.innerHTML = '<span class="badge bg-warning text-dark"><i class="bi bi-clock"></i> Pending</span>';
            } else {
                glCell.innerHTML = '<span class="badge bg-secondary"><i class="bi bi-dash-circle"></i> Excluded</span>';
            }
        }
    })
    .catch(() => {
        alert('Network error. Please try again.');
        this.checked = !include;
    });
}

document.querySelectorAll('.include-txn-cb').forEach(cb => {
    cb.addEventListener('change', toggleTransaction);
});

// ── Summary counter ─────────────────────────────────────────────
function updateSummary() {
    const paid = document.querySelectorAll('.dues-paid-cb:checked').length;
    const total = document.querySelectorAll('.dues-paid-cb').length;
    const paidCard = document.getElementById('paid-count');
    if (paidCard) paidCard.textContent = paid;
    // unpaid is sibling card (second card body)
    const cards = document.querySelectorAll('.row.g-3 .card .fs-4');
    if (cards[1]) cards[1].textContent = total - paid;
}
</script>
{% endblock %}

{% extends "base.html" %}

{% block title %}New Transaction{% endblock %}

{% block content %}
<div class="d-flex justify-content-between flex-wrap flex-md-nowrap align-items-center pt-3 pb-2 mb-3 border-bottom">
    <h1 class="h2">New Transaction</h1>
</div>

<!-- Mode Selector -->
<div class="card mb-3">
    <div class="card-body">
        <div class="btn-group w-100" role="group">
            <input type="radio" class="btn-check" name="mode" id="simpleMode" checked>
            <label class="btn btn-outline-primary" for="simpleMode" onclick="showSimpleMode()">
                <i class="bi bi-lightning"></i> Simple Mode (For Non-Accountants)
            </label>

            <input type="radio" class="btn-check" name="mode" id="accountantMode">
            <label class="btn btn-outline-primary" for="accountantMode" onclick="showAccountantMode()">
                <i class="bi bi-calculator"></i> Accountant Mode (Full Journal Entry)
            </label>
        </div>
    </div>
</div>

<!-- Simple Mode Form -->
<div id="simpleModeForm" class="card">
    <div class="card-header">
        <h5><i class="bi bi-lightning"></i> Simple Transaction Entry</h5>
    </div>
    <div class="card-body">
        <form method="POST" id="simpleForm">
            <input type="hidden" name="entry_mode" value="simple">

            <div class="row">
                <div class="col-md-6 mb-3">
                    <label for="transaction_type" class="form-label">Transaction Type *</label>
                    <select class="form-select" id="transaction_type" name="transaction_type" required>
                        <option value="">-- Select Transaction Type --</option>
                        <optgroup label="Money Coming In">
                            <option value="received_dues">💰 Received Membership Dues</option>
                            <option value="received_donation">🎁 Received Donation</option>
                            <option value="received_grant">🏛️ Received Grant</option>
                        </optgroup>
                        <optgroup label="Money Going Out">
                            <option value="paid_vendor">🛒 Paid Vendor/Supplier</option>
                            <option value="paid_rent">🏢 Paid Rent</option>
                            <option value="paid_utilities">💡 Paid Utilities</option>
                            <option value="paid_salary">👤 Paid Salary/Wages</option>
                        </optgroup>
                    </select>
                    <small class="text-muted">Select what type of transaction this is</small>
                </div>

                <div class="col-md-6 mb-3">
                    <label for="amount" class="form-label">Amount ($) *</label>
                    <input type="number" step="0.01" class="form-control" id="amount" name="amount" required>
                </div>
            </div>

            <div class="row">
                <div class="col-md-6 mb-3">
                    <label for="project_id" class="form-label">Project *</label>
                    <select class="form-select" id="project_id" name="project_id" required>
                        <option value="">-- Select Project --</option>
                        {% for project in projects %}
                        <option value="{{ project.id }}">{{ project.name }}</option>
                        {% endfor %}
                    </select>
                </div>

                <div class="col-md-6 mb-3">
                    <label for="entry_date" class="form-label">Date *</label>
                    <input type="date" class="form-control" id="entry_date" name="entry_date" 
                           value="{{ today }}" required>
                </div>
            </div>

            <div class="mb-3">
                <label for="description" class="form-label">Description *</label>
                <input type="text" class="form-control" id="description" name="description" 
                       placeholder="e.g., Monthly dues from John Smith" required>
            </div>

            <div class="mb-3">
                <label for="reference_number" class="form-label">Reference Number</label>
                <input type="text" class="form-control" id="reference_number" name="reference_number" 
                       placeholder="Check #, Invoice #, etc.">
            </div>

            <div class="alert alert-info">
                <i class="bi bi-info-circle"></i> <strong>How it works:</strong> 
                The system automatically creates the proper accounting entries for you. 
                Just select the transaction type, enter the amount, and describe what it's for!
            </div>

            <div class="d-grid gap-2 d-md-flex justify-content-md-end">
                <a href="/transactions" class="btn btn-secondary">Cancel</a>
                <button type="submit" class="btn btn-primary">
                    <i class="bi bi-check-circle"></i> Post Transaction
                </button>
            </div>
        </form>
    </div>
</div>

<!-- Accountant Mode Form -->
<div id="accountantModeForm" class="card" style="display: none;">
    <div class="card-header">
        <h5><i class="bi bi-calculator"></i> Full Journal Entry</h5>
    </div>
    <div class="card-body">
        <form method="POST" id="accountantForm">
            <input type="hidden" name="entry_mode" value="accountant">

            <div class="row">
                <div class="col-md-6 mb-3">
                    <label for="project_id_acct" class="form-label">Project *</label>
                    <select class="form-select" id="project_id_acct" name="project_id" required>
                        <option value="">-- Select Project --</option>
                        {% for project in projects %}
                        <option value="{{ project.id }}">{{ project.name }}</option>
                        {% endfor %}
                    </select>
                </div>

                <div class="col-md-6 mb-3">
                    <label for="entry_date_acct" class="form-label">Date *</label>
                    <input type="date" class="form-control" id="entry_date_acct" name="entry_date" 
                           value="{{ today }}" required>
                </div>
            </div>

            <div class="mb-3">
                <label for="description_acct" class="form-label">Description *</label>
                <input type="text" class="form-control" id="description_acct" name="description" required>
            </div>

            <div class="mb-3">
                <label for="reference_number_acct" class="form-label">Reference Number</label>
                <input type="text" class="form-control" id="reference_number_acct" name="reference_number">
            </div>

            <hr>

            <h6>Journal Entry Lines</h6>
            <div class="table-responsive">
                <table class="table" id="journalLines">
                    <thead>
                        <tr>
                            <th style="width: 40%;">Account</th>
                            <th style="width: 20%;">Debit</th>
                            <th style="width: 20%;">Credit</th>
                            <th style="width: 15%;">Memo</th>
                            <th style="width: 5%;"></th>
                        </tr>
                    </thead>
                    <tbody id="linesBody">
                        <tr class="journal-line">
                            <td>
                                <select class="form-select form-select-sm" name="account_id[]" required>
                                    <option value="">-- Select Account --</option>
                                    {% for account in accounts %}
                                    <option value="{{ account.id }}">{{ account.account_number }} - {{ account.account_name }}</option>
                                    {% endfor %}
                                </select>
                            </td>
                            <td><input type="number" step="0.01" class="form-control form-control-sm debit-input" name="debit_amount[]" placeholder="0.00"></td>
                            <td><input type="number" step="0.01" class="form-control form-control-sm credit-input" name="credit_amount[]" placeholder="0.00"></td>
                            <td><input type="text" class="form-control form-control-sm" name="memo[]"></td>
                            <td></td>
                        </tr>
                    </tbody>
                    <tfoot>
                        <tr>
                            <td><strong>TOTALS:</strong></td>
                            <td><strong id="totalDebits">$0.00</strong></td>
                            <td><strong id="totalCredits">$0.00</strong></td>
                            <td colspan="2">
                                <span id="balanceStatus" class="badge bg-secondary">Not Balanced</span>
                            </td>
                        </tr>
                    </tfoot>
                </table>
            </div>

            <button type="button" class="btn btn-sm btn-outline-primary" onclick="addLine()">
                <i class="bi bi-plus-circle"></i> Add Line
            </button>

            <div class="alert alert-warning mt-3">
                <i class="bi bi-exclamation-triangle"></i> <strong>Double-Entry Accounting:</strong> 
                Total debits must equal total credits. The system will not allow unbalanced entries.
            </div>

            <div class="d-grid gap-2 d-md-flex justify-content-md-end mt-3">
                <a href="/transactions" class="btn btn-secondary">Cancel</a>
                <button type="submit" class="btn btn-primary" id="submitBtn" disabled>
                    <i class="bi bi-check-circle"></i> Post Journal Entry
                </button>
            </div>
        </form>
    </div>
</div>

{% endblock %}

{% block scripts %}
<script>
function showSimpleMode() {
    document.getElementById('simpleModeForm').style.display = 'block';
    document.getElementById('accountantModeForm').style.display = 'none';
}

function showAccountantMode() {
    document.getElementById('simpleModeForm').style.display = 'none';
    document.getElementById('accountantModeForm').style.display = 'block';
    calculateTotals();
}

function addLine() {
    const tbody = document.getElementById('linesBody');
    const firstRow = tbody.querySelector('.journal-line');
    const newRow = firstRow.cloneNode(true);

    // Clear values
    newRow.querySelectorAll('input, select').forEach(input => {
        if (input.tagName === 'SELECT') {
            input.selectedIndex = 0;
        } else {
            input.value = '';
        }
    });

    // Add delete button to new row
    const deleteCell = newRow.querySelector('td:last-child');
    deleteCell.innerHTML = '<button type="button" class="btn btn-sm btn-outline-danger" onclick="removeLine(this)"><i class="bi bi-trash"></i></button>';

    tbody.appendChild(newRow);

    // Add event listeners
    newRow.querySelectorAll('.debit-input, .credit-input').forEach(input => {
        input.addEventListener('input', calculateTotals);
        input.addEventListener('input', enforceDebitOrCredit);
    });
}

function removeLine(btn) {
    const tbody = document.getElementById('linesBody');
    if (tbody.querySelectorAll('.journal-line').length > 1) {
        btn.closest('tr').remove();
        calculateTotals();
    }
}

function enforceDebitOrCredit(e) {
    const row = e.target.closest('tr');
    const debitInput = row.querySelector('.debit-input');
    const creditInput = row.querySelector('.credit-input');

    if (e.target.classList.contains('debit-input') && parseFloat(e.target.value) > 0) {
        creditInput.value = '';
    } else if (e.target.classList.contains('credit-input') && parseFloat(e.target.value) > 0) {
        debitInput.value = '';
    }
}

function calculateTotals() {
    let totalDebits = 0;
    let totalCredits = 0;

    document.querySelectorAll('.debit-input').forEach(input => {
        totalDebits += parseFloat(input.value) || 0;
    });

    document.querySelectorAll('.credit-input').forEach(input => {
        totalCredits += parseFloat(input.value) || 0;
    });

    document.getElementById('totalDebits').textContent = '$' + totalDebits.toFixed(2);
    document.getElementById('totalCredits').textContent = '$' + totalCredits.toFixed(2);

    const diff = Math.abs(totalDebits - totalCredits);
    const balanced = diff < 0.01 && totalDebits > 0;

    const statusBadge = document.getElementById('balanceStatus');
    const submitBtn = document.getElementById('submitBtn');

    if (balanced) {
        statusBadge.className = 'badge bg-success';
        statusBadge.textContent = '✓ Balanced';
        submitBtn.disabled = false;
    } else {
        statusBadge.className = 'badge bg-danger';
        statusBadge.textContent = '✗ Not Balanced (Diff: $' + diff.toFixed(2) + ')';
        submitBtn.disabled = true;
    }
}

// Add event listeners on page load
document.addEventListener('DOMContentLoaded', function() {
    document.querySelectorAll('.debit-input, .credit-input').forEach(input => {
        input.addEventListener('input', calculateTotals);
        input.addEventListener('input', enforceDebitOrCredit);
    });
});
</script>
{% endblock %}

